#!/usr/bin/env python3
"""Validate this store package — GENERATED by `scripts/build_store_package.py`.

    python3 store/v1.2.1/check.py           # verify, exit 1 on any blocker
    python3 store/v1.2.1/check.py --write   # rewrite the Apple "What's New" from the app's
                                            # own patch notes

The checks themselves live in `scripts/store_check.py` — one implementation, not a copy
per release. `VERSION` below is pinned on purpose: this package is the record of what
was published as 1.2.1, and a released listing does not track the working tree. Before
this shim existed, each package's checker read `pubspec.yaml`, so the day 1.3.0 was
bumped, v1.2.1's own checker began comparing v1.2.1's published notes against 1.3.0's
patch notes and raised three blockers on files that had not changed and must not change.
"""

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "scripts"))

from store_check import main  # noqa: E402

VERSION = "1.2.1"

if __name__ == "__main__":
    sys.exit(main(Path(__file__).resolve().parent, VERSION,
                  "--write" in sys.argv))
